local config = {
  ui_story_31880401_1_dialog_content = "<color=#e8d9bb>A poem reads...</color>",
  ui_story_31880401_2_dialog_content = "<color=#e8d9bb>\"The King of Ji, a vassal kingdom of the Zhao Empire, ordered Princess Zhuohua to travel as an envoy to the western lands.\"</color>",
  ui_story_31880401_3_dialog_content = "<color=#e8d9bb>\"Fearlessly, she ventured across mountains and oceans, even amidst border skirmishes, displaying unwavering courage in the face of hardship.\"</color>",
  ui_story_31880401_4_dialog_content = "<color=#e8d9bb>\"As she wandered through a vast desert, loneliness and desperation swelled within her heart. Under a cold, clear sky, her emotions became complicated and intense.\"</color>",
  ui_story_31880401_5_dialog_content = "<color=#e8d9bb>\"To add to her woes, a flock of geese cried out in the direction of Twin Pavilions Bay, and she was overwhelmed by her isolation and homesickness.\"</color>",
  ui_story_31880401_6_dialog_content = "<color=#e8d9bb>In spite of her countless trials and tribulations, Princess Zhuohua had finally arrived in the western lands, and so she stopped in Twin Pavilions Bay for a brief respite.</color>",
  ui_story_31880401_7_dialog_content = "<color=#e8d9bb>As its name suggests, Twin Pavilions Bay is a city divided in two, with one half ruled by Umbraton and the other by the Lin Guild.</color>",
  ui_story_31880401_8_dialog_content = "<color=#e8d9bb>In the Lin Guild's half of the city, the streets and buildings look no different than those of the great city of the Zhao Empire. It confuses people sometimes, not knowing where they are.</color>",
  ui_story_31880401_9_dialog_content = "<color=#e8d9bb>Dragon Horse Bai, Jiu Wukong, Meow Bajie, and Zen Wujing gazed in awe at Umbraton's half of the city, their hearts full of ambition.</color>",
  ui_story_31880401_10_dialog_content = "<color=#e8d9bb>Princess Zhuohua, however, stared blankly at a mirror, her mind apparently occupied by something troubling...</color>",
  ui_story_31880401_11_dialog_content = "<color=#e8d9bb>The beautiful face reflected in the mirror calls to mind yet another poem...</color>",
  ui_story_31880401_12_dialog_content = "<color=#e8d9bb>\"Skin as white as ice, and features as fine as carved jade. Her rosy cheeks and bright-red lips fill this world with color and beauty.\"</color>",
  ui_story_31880401_13_dialog_content = "<color=#e8d9bb>\"Softly she treads, as light and elegant as a breeze through a willow's branches. Her eyes call to mind the tenderness of flower petals falling gently upon a pool of water.\"</color>",
  ui_story_31880401_14_dialog_content = "Wukong, how long has it been since we sent a letter to the Obsidian Lion King requesting an audience?",
  ui_story_31880401_15_dialog_content = "Fifteen days, if we include today.",
  ui_story_31880401_16_dialog_content = "The Obsidian Lion King appears to be too busy to reply to us.",
  ui_story_31880401_17_dialog_content = "Not good! Not good!",
  ui_story_31880401_18_dialog_content = "Why are you in such a panic, Bajie?",
  ui_story_31880401_19_dialog_content = "I went to check on the Obsidian Lion King's house, and I found our letter in the trash! They threw it out!",
  ui_story_31880401_20_dialog_content = "What?",
  ui_story_31880401_21_dialog_content = "Wujing saw it too! Ask him if you don't believe me!",
  ui_story_31880401_22_dialog_content = "He's telling the truth, Your Highness. I saw it as well.",
  ui_story_31880401_23_dialog_content = "... No wonder we have yet to receive a reply.",
  ui_story_31880401_24_dialog_content = "It seems we're hardly worthy of the Obsidian Lion King's attention.",
  ui_story_31880401_25_dialog_content = "Umbraton is far from the only place here in Astra. If we continue traveling west, we can visit the Illumina or even Eraveil.",
  ui_story_31880401_26_dialog_content = "Agreed! If they won't give us the time of day, then neither should we!",
  ui_story_31880401_27_dialog_content = "This Lion King hardly seems like a king anyway. As far as I'm concerned, he's just another brainless lion!",
  ui_story_31880401_28_dialog_content = "What do you say, Your Highness? Should I go and teach them a lesson?",
  ui_story_31880401_29_dialog_content = "Absolutely not.",
  ui_story_31880401_30_dialog_content = "We aren't here to cause trouble. Remember to keep our ultimate goal in mind.",
  ui_story_31880401_31_dialog_content = "It's always \"ultimate goal\" this and \"ultimate goal\" that. How am I supposed to keep it in mind if I'm not even allowed to go out other than check on that lion?",
  ui_story_31880401_32_dialog_content = "That's enough, Bajie.",
  ui_story_31880401_33_dialog_content = "For the last few days, I was worried we would miss our chance to meet the Obsidian Lion King if we wandered about too much.",
  ui_story_31880401_34_dialog_content = "But it seems we no longer need to worry about that.",
  ui_story_31880401_35_dialog_content = "Here, Wukong. Take the silver, along with Bajie and Wujing, and go enjoy yourselves.",
  ui_story_31880401_36_dialog_content = "But what about you, Your Highness?",
  ui_story_31880401_37_dialog_content = "I think I'll just stay here and rest for a while. You three go ahead.",
  ui_story_31880401_38_dialog_content = "Get plenty of rest then, Your Highness! We'll bring you some candied fruit later!",
  ui_story_31880401_39_dialog_content = "Your Highness! Are you awake yet?",
  ui_story_31880401_40_dialog_content = "These candied fruits taste just like the ones back home! Here, try some!",
  ui_story_31880401_41_dialog_content = "Huh? Wh-Where's Her Highness?!",
  ui_story_31880401_42_dialog_content = "She didn't leave us behind to go have fun all by herself, did she?!",
  ui_story_31880401_43_dialog_content = "No, her shawl is still here, which means Her Highness likely didn't leave on her own accord. If anything...",
  ui_story_31880401_44_dialog_content = "If anything...?",
  ui_story_31880401_45_dialog_content = "It looks like a kidnap.",
  ui_story_31880401_46_dialog_content = "What?!",
  ui_story_31880401_47_dialog_content = "But we haven't bothered anyone here! Why would they kidnap Her Highness?",
  ui_story_31880401_48_dialog_content = "Aside from us, there's only one person who knows that Her Highness is here right now.",
  ui_story_31880401_49_dialog_content = "The Obsidian Lion King?",
  ui_story_31880401_50_dialog_content = "I'll transform into an insect and go investigate. You two stay here and keep your heads down.",
  ui_story_31880401_51_dialog_content = "<color=#e8d9bb>Poof!</color>",
  ui_story_31880401_52_dialog_content = "Who knew this guy had a hidden room in his house like this?",
  ui_story_31880401_53_dialog_content = "Hmm? There's someone up ahead!",
  ui_story_31880401_54_dialog_content = "Unhand me!",
  ui_story_31880401_55_dialog_content = "Hahaha! Don't you think your struggles are all but in vain now?",
  ui_story_31880401_56_dialog_content = "You... What exactly are you plotting?",
  ui_story_31880401_57_dialog_content = "I could ask you the very same question. Tell me, why have you come to Astra?",
  ui_story_31880401_58_dialog_content = "I made it very clear in the letter. We're here on a cultural exchange mission...",
  ui_story_31880401_59_dialog_content = "A \"cultural exchange\"? What a pleasant way of phrasing it.",
  ui_story_31880401_60_dialog_content = "You can dispense with the act now. We know you're working as a spy for the east.",
  ui_story_31880401_61_dialog_content = "Though you claim to seek a cultural exchange, what you truly seek are Astra's most well-kept secrets.",
  ui_story_31880401_62_dialog_content = "You're wrong!",
  ui_story_31880401_63_dialog_content = "Then tell me, what would happen if we successfully entered into a trade agreement?",
  ui_story_31880401_64_dialog_content = "Both the east and west would benefit greatly from it. Western machinery would appear in the east, and eastern ingenuity would come here.",
  ui_story_31880401_65_dialog_content = "How very wrong you are.",
  ui_story_31880401_66_dialog_content = "When the time comes, your people will mark down the prices of your goods and inundate all of Astra with them.",
  ui_story_31880401_67_dialog_content = "Once our domestic markets are crippled and our people have no way of making a living...",
  ui_story_31880401_68_dialog_content = "Your emperor will send his forces to attack and conquer all of Astra!",
  ui_story_31880401_69_dialog_content = "That's absurd!",
  ui_story_31880401_70_dialog_content = "I didn't travel thousands of miles to Astra just to create even more conflict between our cultures...",
  ui_story_31880401_71_dialog_content = "Oh? Still denying it?",
  ui_story_31880401_72_dialog_content = "Then let me ask you one final question.",
  ui_story_31880401_73_dialog_content = "My sources tell me that whoever takes the power in your body can become the most powerful Aurorian in existence. Is that true?",
  ui_story_31880401_74_dialog_content = "Wh... What are you planning to do to me?!",
  ui_story_31880401_75_dialog_content = "Oh, look at you, it appears to be the truth.",
  ui_story_31880401_76_dialog_content = "...!!!",
  ui_story_31880401_77_dialog_content = "Buzz, buzz, buzz!",
  ui_story_31880401_78_dialog_content = "Where did this bug come from?",
  ui_story_31880401_79_dialog_content = "<color=#e8d9bb>Smack!</color>",
  ui_story_31880401_80_dialog_content = "What did you say?!",
  ui_story_31880401_81_dialog_content = "So that monster wants to steal Her Highness' power?",
  ui_story_31880401_82_dialog_content = "Why didn't I think of that possibility...?",
  ui_story_31880401_83_dialog_content = "Hey, wait a minute. With Her Highness absent, doesn't that mean I can go wherever I want?",
  ui_story_31880401_84_dialog_content = "...",
  ui_story_31880401_85_dialog_content = "Hey, hey! Her Highness said you can't hit me!",
  ui_story_31880401_86_dialog_content = "I wasn't going to. Now listen carefully, we each have a job to do now...",
  ui_story_31880401_87_dialog_content = "Come out, lion monster! I know you're in there!",
  ui_story_31880401_88_dialog_content = "If you have the guts to kidnap our princess, you should have the guts to admit it too!",
  ui_story_31880401_89_dialog_content = "How dare you come to bark at my door like a stray dog?",
  ui_story_31880401_90_dialog_content = "H-He came out... It's up to you now, Wujing!",
  ui_story_31880401_91_dialog_content = "Yes, yes, I know.",
  ui_story_31880401_92_dialog_content = "Prepare yourself, Obsidian Lion King! Now that you've kidnapped our princess, I have no reason to hold back!",
  ui_story_31880401_93_dialog_content = "Take this!",
  ui_story_31880401_94_dialog_content = "Hmph, such petty tricks.",
  ui_story_31880401_95_dialog_content = "Urgh...",
  ui_story_31880401_96_dialog_content = "H-He's too strong! We should just run—",
  ui_story_31880401_97_dialog_content = "Leaving so soon? Have you forgotten where you are right now?",
  ui_story_31880401_98_dialog_content = "You won't escape so easily!",
  ui_story_31880401_99_dialog_content = "...",
  ui_story_31880401_100_dialog_content = "Wait, are they... trying to lure me away?",
  ui_story_31880401_101_dialog_content = "Urgh... What...",
  ui_story_31880401_102_dialog_content = "Hmph, don't bother searching. The princess is safe and sound now.",
  ui_story_31880401_103_dialog_content = "Now we can really have some fun.",
  ui_story_31880401_104_dialog_content = "Take this!",
  ui_story_31880401_105_dialog_content = "Wait!",
  ui_story_31880401_106_dialog_content = "Dragon Horse Bai? Aren't you supposed to be watching our equipment?",
  ui_story_31880401_107_dialog_content = "I found the Obsidian Lion King's daughter—the Bell Fairy.",
  ui_story_31880401_108_dialog_content = "Everyone, please lower your weapons.",
  ui_story_31880401_109_dialog_content = "Master...",
  ui_story_31880401_110_dialog_content = "\"Master\"? That's a new one. Why would your father call you that?",
  ui_story_31880401_111_dialog_content = "See for yourself.",
  ui_story_31880401_112_dialog_content = "<color=#e8d9bb>Poof!</color>",
  ui_story_31880401_113_dialog_content = "...",
  ui_story_31880401_114_dialog_content = "What's this...?",
  ui_story_31880401_115_dialog_content = "This is Frankel, my specter.",
  ui_story_31880401_116_dialog_content = "It appears Frankel assumed my father's appearance while we were away, and caused you no small amount of trouble.",
  ui_story_31880401_117_dialog_content = "Oh? So the one who called me a stray dog was none other than the family pet, eh?",
  ui_story_31880401_118_dialog_content = "Boo-hoo...",
  ui_story_31880401_119_dialog_content = "Mind your tongue, Bajie.",
  ui_story_31880401_120_dialog_content = "Hmph! How could you still be so courteous to them, Your Highness? Did you already forget what happened to you?",
  ui_story_31880401_121_dialog_content = "It was my fault for not training Frankel well enough.",
  ui_story_31880401_122_dialog_content = "Please accept my sincerest apologies!",
  ui_story_31880401_123_dialog_content = "I'll be sure to keep a closer eye on Frankel, so that this never happens again.",
  ui_story_31880401_124_dialog_content = "By way of an apology, allow me to cover your travel expenses as you continue journeying west.",
  ui_story_31880401_125_dialog_content = "And if you would like... I can accompany you to see my father as well, princess.",
  ui_story_31880401_126_dialog_content = "That would most appreciated.",
  ui_story_31880401_127_dialog_content = "<color=#e8d9bb>Shortly afterward, Princess Zhuohua finally gained an audience with the Obsidian Lion King, the ruler of Umbraton.</color>",
  ui_story_31880401_128_dialog_content = "<color=#e8d9bb>But will she truly be capable of accomplishing her cultural exchange mission?",
  ui_story_31880401_129_dialog_content = "<color=#e8d9bb>Read the next chapter to find out!</color>",
  ui_story_31880401_130_dialog_content = "Wow, this book seems...",
  ui_story_31880401_131_option_content = "Hard to understand.",
  ui_story_31880401_132_dialog_content = "Do the novels in the east really have to be so difficult to read?",
  ui_story_31880401_133_dialog_content = "Heheh, we call those \"seven-character poems.\"",
  ui_story_31880401_134_dialog_content = "The literati of Zhao like to write and recite poems like this to express their feelings.",
  ui_story_31880401_135_dialog_content = "It's not uncommon to see them in our novels either.",
  ui_story_31880401_136_option_content = "Really interesting!",
  ui_story_31880401_137_dialog_content = "I don't think I've ever read such an imaginative novel...",
  ui_story_31880401_138_dialog_content = "It feels like I know these characters in real life, but they seem a lot more sophisticated in the story.",
  ui_story_31880401_139_dialog_content = "You were right, this novel is really interesting!",
  ui_story_31880401_140_dialog_content = "It seems sharing this novel with you was the right choice after all.",
  ui_story_31880401_141_dialog_content = "The author works really fast too!",
  ui_story_31880401_142_dialog_content = "You guys haven't been in Astra for very long, but your story is already being published throughout our land!",
  ui_story_31880401_143_dialog_content = "Hmph, looks like another cheap novel to me.",
  ui_story_31880401_144_dialog_content = "I happen to be a famous and well-respected doctor who helps the injured and the suffering.",
  ui_story_31880401_145_dialog_content = "But this story makes me out to be some kind of whiny, lazy cat!",
  ui_story_31880401_146_dialog_content = "What a load of bunk!",
  ui_story_31880401_147_dialog_content = "Oh, don't look at it that way.",
  ui_story_31880401_148_dialog_content = "When traveling the world like we are, having another identity is the same as having another layer of protection.",
  ui_story_31880401_149_dialog_content = "I think these novels are quite well-written.",
  ui_story_31880401_150_dialog_content = "Do you have any other identities, Tianxian?",
  ui_story_31880401_151_dialog_content = "Now, why would you ask about something like that? Secrets aren't meant to be shared, you know!",
  ui_story_31880401_152_dialog_content = "Wait, come back...",
  ui_story_31880401_153_dialog_content = "My investigation is complete, Your Highness.",
  ui_story_31880401_154_dialog_content = "The person who published these novels is a man from the Rediesel Desert by the name of Jomu.",
  ui_story_31880401_155_dialog_content = "The author does not appear to be from Zhao either.",
  ui_story_31880401_156_dialog_content = "This Jomu person seems to be planning a trip to Zhao in order to further his business interests.",
  ui_story_31880401_157_dialog_content = "Do you need me to dispose of him?",
  ui_story_31880401_158_dialog_content = "Oh? I honestly thought these novels were written by one of our countrymen.",
  ui_story_31880401_159_dialog_content = "I had no idea someone in Astra was so well-versed in Zhao's literary style!",
  ui_story_31880401_160_dialog_content = "The free books you brought from Zhou have been widely circulated here. I believe this may have something to do with it.",
  ui_story_31880401_161_dialog_content = "There doesn't seem to be a shortage of talent in Astra then.",
  ui_story_31880401_162_dialog_content = "And Jomu...?",
  ui_story_31880401_163_dialog_content = "He's done well, so we should support his efforts.",
  ui_story_31880401_164_dialog_content = "As an envoy to Astra, this is exactly the type of cultural exchange I wish to promote.",
  ui_story_31880401_165_dialog_content = "Although the story in these novels has been greatly embellished, that shouldn't detract from their value.",
  ui_story_31880401_166_dialog_content = "The expression of different views and ideologies...",
  ui_story_31880401_167_dialog_content = "This is part of the cultural prosperity I seek.",
  ui_story_31880401_168_dialog_content = "Not only that...",
  ui_story_31880401_169_dialog_content = "\"Skin as white as ice, and features as fine as carved jade. Her rosy cheeks and bright-red lips fill this world with color and beauty.\"",
  ui_story_31880401_170_dialog_content = "\"Softly she treads, as light and elegant as a breeze through a willow's branches. Her eyes call to mind the tenderness of flower petals falling gently upon a pool of water.\"",
  ui_story_31880401_171_dialog_content = "As silly as it sounds, I'm still rather fond of these lines.",
  ui_story_31880401_172_dialog_content = "Hehehe!",
  ui_story_31880601_1_dialog_content = "The sound of whispering waves in the gentle night, and the flickering of shadows in the candlelight...",
  ui_story_31880601_2_dialog_content = "Tonight is a beautiful night.",
  ui_story_31880601_3_dialog_content = "It is.",
  ui_story_31880601_4_dialog_content = "Ever since I left my homeland for Ji Kingdom... I've had few opportunities for leisurely moments such as this.",
  ui_story_31880601_5_dialog_content = "Thank you so much for inviting me to admire the moon from the beach.",
  ui_story_31880601_6_dialog_content = "Your gracious offer has brought me much joy today.",
  ui_story_31880601_7_dialog_content = "You don't have to be so polite! I'm having a good time too...",
  ui_story_31880601_8_dialog_content = "Heheh, it seems today's moon-viewing was a resounding success for both of us.",
  ui_story_31880601_9_dialog_content = "Allow me to make a toast to you, my friend...",
  ui_story_31880601_10_dialog_content = "Ahh, the sound of the waves is truly comforting... It really calls to mind a certain memory from my past.",
  ui_story_31880601_11_dialog_content = "A certain memory?",
  ui_story_31880601_12_dialog_content = "Yes. At the time, I had just arrived in the Ji Kingdom, and I spent much of my time near the harbor.",
  ui_story_31880601_13_dialog_content = "My homeland, the Ye Kingdom, is known for its expert artisanship, as well as its profound knowledge of machinery...",
  ui_story_31880601_14_dialog_content = "But I had never encountered such a thriving land of commerce and competition. It was truly a sight to behold.",
  ui_story_31880601_15_dialog_content = "It was such an eye-opening experience for someone who had just arrived... Back then, I'd often gaze into the distance, lost in my own thoughts.",
  ui_story_31880601_16_dialog_content = "Out on the horizon, where the boundless sky meets the vast sea, countless ships carrying all kinds of wonders sailed to and from...",
  ui_story_31880601_17_dialog_content = "Uh-huh...",
  ui_story_31880601_18_dialog_content = "Is something the matter? Or is it getting too late for you?",
  ui_story_31880601_19_option_content = "Huh? No... Please go on...",
  ui_story_31880601_20_option_content = "I'm just... a little tired...",
  ui_story_31880601_21_dialog_content = "Heheh, feel free to rest your eyes for a while.",
  ui_story_31880601_22_dialog_content = "Right here, next to me...",
  ui_story_31880601_23_dialog_content = "...",
  ui_story_31880601_24_dialog_content = "... Huh? Where am I? What's this place?",
  ui_story_31880601_25_dialog_content = "Pardon me, but are you alright?",
  ui_story_31880601_26_dialog_content = "D... Dantang?",
  ui_story_31880601_27_dialog_content = "Hmm? I don't believe we've met before. How do you know my name, sir?",
  ui_story_31880601_28_dialog_content = "Could it be that... I've already become well-known?",
  ui_story_31880601_29_dialog_content = "Uh, how should I explain this... I'm pretty sure I'm dreaming right now.",
  ui_story_31880601_30_dialog_content = "Heheh, it would be quite interesting if this was all but a dream.",
  ui_story_31880601_31_dialog_content = "Tell me, what does a dreamer like yourself make of this place?",
  ui_story_31880601_32_dialog_content = "This is your first time at the Ji Kingdom harbor, yes?",
  ui_story_31880601_33_dialog_content = "My first time in a dream.",
  ui_story_31880601_34_dialog_content = "Then it seems you're in need of a guide.",
  ui_story_31880601_35_dialog_content = "The truth is, I haven't been in this city for very long either.",
  ui_story_31880601_36_dialog_content = "But I'm quite familiar with this part of town, as I often come here.",
  ui_story_31880601_37_dialog_content = "You're more than welcome to join me, if you would like?",
  ui_story_31880601_38_dialog_content = "In a few minutes, we should be able to see many large ships.",
  ui_story_31880601_39_dialog_content = "Large ships?",
  ui_story_31880601_40_dialog_content = "Yes, enormous ones that are as big as... Oh look, they're here!",
  ui_story_31880601_41_dialog_content = "As big as houses, and their huge sails billow like clouds in the sky... It's truly breathtaking.",
  ui_story_31880601_42_dialog_content = "I pray that I can board one of those ships someday.",
  ui_story_31880601_43_dialog_content = "Where would you go?",
  ui_story_31880601_44_dialog_content = "Where would I go? Now that you mention it... I've never given it much thought.",
  ui_story_31880601_45_dialog_content = "The guards say that these ships brave treacherous waves and howling storms to trade with distant lands.",
  ui_story_31880601_46_dialog_content = "The stalwart folks aboard these vessels trade goods for gold and vice versa.",
  ui_story_31880601_47_dialog_content = "Constantly traveling in every direction with nary a moment's respite... No one can fathom what compels them to do so.",
  ui_story_31880601_48_dialog_content = "But I envy them all the same.",
  ui_story_31880601_49_dialog_content = "I wouldn't envy them too much. Long voyages like that can be really dangerous.",
  ui_story_31880601_50_dialog_content = "The people here would agree as well. The guards, the dock workers, and everyone else.",
  ui_story_31880601_51_dialog_content = "With every wave of departures, there are always ships that never return.",
  ui_story_31880601_52_dialog_content = "Perhaps they lost their way at sea, or were attacked by wicked ocean spirits.",
  ui_story_31880601_53_dialog_content = "There are even stories of men falling in love with the sea god's daughters, marrying them and losing all hope of returning to land.",
  ui_story_31880601_54_dialog_content = "Whenever a ship embarks on another voyage, there's always talk of destiny, danger, and undiscernible omens...",
  ui_story_31880601_55_dialog_content = "But in spite of everything, I still wish to ride aboard one of those enormous vessels.",
  ui_story_31880601_56_dialog_content = "Even though you know it's dangerous? Why would you want to do that?",
  ui_story_31880601_57_dialog_content = "Because aside from their cargo, these ships also bear so many people's hopes and dreams...",
  ui_story_31880601_58_dialog_content = "And I wish to see for myself the places in which these hopes and dreams are realized!",
  ui_story_31880601_59_dialog_content = "By doing so, I might become someone capable of realizing the wishes of the people...",
  ui_story_31880601_60_dialog_content = "You see... How should I put it...?",
  ui_story_31880601_61_dialog_content = "... Never mind! I'd sound like a daydreaming little girl...",
  ui_story_31880601_62_dialog_content = "Hahaha, don't worry about it! I'm sure you'll be able to express yourself clearly as you grow older.",
  ui_story_31880601_63_dialog_content = "There's nothing wrong with having a dream or talking about it, for that matter.",
  ui_story_31880601_64_dialog_content = "I agree! Then when I grow up, I'll definitely hop on one of those ships for sure!",
  ui_story_31880601_65_dialog_content = "I'll see for myself what lies beyond and beneath the sea! And when that day comes, I'll know exactly how to describe the feelings in my heart.",
  ui_story_31880601_66_dialog_content = "Then I'll be waiting for you on the other side of the sea.",
  ui_story_31880601_67_dialog_content = "You promise?",
  ui_story_31880601_68_dialog_content = "I promise.",
  ui_story_31880601_69_dialog_content = "... You promise...?",
  ui_story_31880601_70_dialog_content = "Did I...?",
  ui_story_31880601_71_dialog_content = "Ah, you're awake. You weren't asleep for very long though.",
  ui_story_31880601_72_dialog_content = "Did you dream of something?",
  ui_story_31880601_73_dialog_content = "Dantang...?",
  ui_story_31880601_74_dialog_content = "Hmm... I don't remember it very clearly, but I definitely had a dream just now.",
  ui_story_31880601_75_dialog_content = "Really? You were talking in your sleep as well, mumbling about ships and promises and such.",
  ui_story_31880601_76_dialog_content = "May I ask what you were dreaming about?",
  ui_story_31880601_77_dialog_content = "It's kind of hard to explain... Somehow I feel like it happened a long time ago...",
  ui_story_31880601_78_dialog_content = "Heheh, you really are an interesting person.",
  ui_story_31880601_79_dialog_content = "Transcending time through dreams... The notion definitely inspires thought.",
  ui_story_31880601_80_dialog_content = "Heh, I promise I'm not trying to sound confusing or anything. Putting it into words really is a little difficult...",
  ui_story_31880601_81_dialog_content = "Because of our psychic abilities, entering and interpreting dreams is pretty easy...",
  ui_story_31880601_82_dialog_content = "I've also used a similar dream technique to see what's in other people's hearts.",
  ui_story_31880601_83_dialog_content = "It helps me solve a lot of problems in the real world that I'd otherwise have no way of solving.",
  ui_story_31880601_84_dialog_content = "Which is why my own dreams are usually a subconscious combination of information...",
  ui_story_31880601_85_dialog_content = "It's like my brain is working overtime in my sleep, piecing together bits and pieces of knowledge that I gain during the day...",
  ui_story_31880601_86_dialog_content = "Pfft—",
  ui_story_31880601_87_dialog_content = "Oh! Sorry, I didn't say something weird just now, did I...?",
  ui_story_31880601_88_dialog_content = "Not at all! After all, we're talking about dreams.",
  ui_story_31880601_89_dialog_content = "Thinking back, I dreamed quite often during my formative years in the Ji Kingdom.",
  ui_story_31880601_90_dialog_content = "Sometimes I'd even dream of riding atop an enormous ship as it set sail for another voyage...",
  ui_story_31880601_91_dialog_content = "Do you still dream of going out to sea?",
  ui_story_31880601_92_dialog_content = "Absolutely, though my dreams aren't nearly as mysterious anymore.",
  ui_story_31880601_93_dialog_content = "After all, I've even ridden aboard your Colossus now.",
  ui_story_31880601_94_dialog_content = "Now that you mention it... If none of this had ever happened, would you still want to go out to sea?",
  ui_story_31880601_95_dialog_content = "There's no denying going on an ocean voyage is no different than placing your life in the hands of destiny.",
  ui_story_31880601_96_dialog_content = "But by choosing to go out to sea, isn't it the same as taking destiny into one's own hands as well?",
  ui_story_31880601_97_dialog_content = "But you still might end up in the belly of a giant fish.",
  ui_story_31880601_98_dialog_content = "From the moment I was born, my destiny was allegedly set in stone, and the people of the Ye Kingdom came to regard me as an ill-fated soul.",
  ui_story_31880601_99_dialog_content = "But in my travels, I've learned that destiny is not nearly as immutable as we believe.",
  ui_story_31880601_100_dialog_content = "Which is why I believe we as people have the power to fight back against the unknown, and even the heavens themselves.",
  ui_story_31880601_101_dialog_content = "What about you? What would you do?",
  ui_story_31880601_102_dialog_content = "If you were faced with an opportunity like this, would you choose to set sail as well?",
  ui_story_31880601_103_option_content = "I'd go out to sea!",
  ui_story_31880601_104_dialog_content = "As expected, you and I are of the same thinking.",
  ui_story_31880601_105_option_content = "I have my own path to take!",
  ui_story_31880601_106_dialog_content = "You're absolutely right. After all, your fate is in your own hands.",
  ui_story_31880601_107_dialog_content = "There's no need to follow in the footsteps of others, or to do what has already been done by them.",
  ui_story_31880601_108_dialog_content = "You need only keep your own destiny in sight, and take a firm hold of it.",
  ui_story_31880601_109_dialog_content = "That way, whether at sea or in the face of unexpected change, you'll never lose your way.",
  ui_story_31880601_110_dialog_content = "And if you do happen to get lost, all you need to do is look back.",
  ui_story_31880601_111_dialog_content = "There will always be someone waiting for you.",
  ui_story_31880601_112_dialog_content = "I should've known... The answer you found after growing up...",
  ui_story_31880601_113_dialog_content = "Is way more incredible than I could've imagined!",
  ui_story_31880601_114_dialog_content = "Hmm? I don't understand...",
  ui_story_31880601_115_dialog_content = "I-It's nothing! Sorry to interrupt!",
  ui_story_31880601_116_dialog_content = "Now where were we... Oh—I'll always be waiting behind you too, Dantang!",
  ui_story_31880601_117_dialog_content = "PlayerName...",
  ui_story_31880601_118_dialog_content = "I mean it... So let's keep talking... I-I promise I'm... not that tired...",
  ui_story_31880601_119_dialog_content = "Oh? It seems we've stayed up a bit too late. You need your rest as well.",
  ui_story_31880601_120_dialog_content = "The moon has hidden itself behind a veil of dark clouds, so let's end tonight's viewing for now.",
  ui_story_31880601_121_dialog_content = "Allow me to walk you back to your quarters.",
  ui_story_31880601_122_dialog_content = "Please get plenty of rest. There will be many dreams to realize for the two lands in the future..."
}
return config
